(() => {
'use strict';
const root=document.getElementById('access-routing');if(!root)return;
const by=id=>document.getElementById('ctrl-'+id);
let mode='auth';let state={origin:'same',credential:'valid',browser:'present',resource:'own',group:'office',department:'general',load:0,locality:true,memory:false};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(key,label,choices)=>`<label>${label}<select data-ctrl="${key}">${choices.map(([v,t])=>`<option value="${v}"${state[key]===v?' selected':''}>${t}</option>`).join('')}</select></label>`;
const card=(title,sub,status='')=>`<div class="ctrl-node ${status}"><span>${title}</span><strong>${sub}</strong></div>`;
function controls(){let c='';if(mode==='auth')c=select('origin','Origin / cross-site guard',[['same','Same origin'],['cross','Rejected cross-site request']])+select('credential','Department credential',[['valid','Valid'],['invalid','Invalid / absent']])+select('browser','Browser identity',[['present','Initialized'],['missing','Missing']])+select('resource','Requested resource',[['own','Owned thread'],['foreign','Another browser’s thread'],['global','Unscoped global runs']]);
if(mode==='routing')c=select('group','Application profile',[['office','Office · 6 departments'],['ops','Operations · 4 departments']])+select('department','Selected department',state.group==='office'?[['general','General office'],['finance','Finance'],['legal','Legal']]:[['general','General operations'],['works','Infrastructure'],['signal','Signals']]);
if(mode==='scheduling')c=`<label class="ctrl-range">Worker A queue <input type="range" data-ctrl="load" min="0" max="8" step="1" value="${state.load}"><output id="ctrl-load-value">${state.load} jobs</output></label><label class="ctrl-check"><input type="checkbox" data-ctrl="locality"${state.locality?' checked':''}>Consider matching prefix</label><label class="ctrl-check"><input type="checkbox" data-ctrl="memory"${state.memory?' checked':''}>Worker A lacks KV reserve</label>`;
by('controls').innerHTML=c;}
function auth(){const gates=[['Origin',state.origin==='same','403 / cross_origin_request'],['Department',state.credential==='valid','401 / invalid_department_credentials'],['Browser',state.browser==='present','401 / browser_identity_required'],['Route scope',state.resource!=='global','403 / private_route_required'],['Thread owner',state.resource!=='foreign','404 / thread_not_found']];const failure=gates.findIndex(g=>!g[1]);
by('visual').innerHTML='<div class="ctrl-auth-flow">'+gates.map(([name,pass],i)=>`${i?'<span class="ctrl-arrow" aria-hidden="true">→</span>':''}${card(name,i===failure?'DENY':failure<0||i<failure?'PASS':'NOT REACHED',i===failure?'ctrl-denied':failure<0||i<failure?'ctrl-ok':'ctrl-idle')}`).join('')+'</div><div class="ctrl-outcome '+(failure>=0?'ctrl-denied':'ctrl-ok')+'"><span>PROXY RESULT</span><strong>'+(failure>=0?gates[failure][2]:'Forward to the selected department backend')+'</strong><small>'+(failure>=0?'No new Agent run is forwarded.':'The model receives the task only after this boundary permits the request.')+'</small></div>';
by('status').textContent=failure>=0?`Stopped at ${gates[failure][0].toLowerCase()}. ${state.resource==='foreign'&&failure===4?'A missing and an unowned thread both return 404.':'Subsequent gates are not evaluated in this demonstration.'}`:'Registered department + initialized browser + owned thread: the proxy forwards the request. The Agent cannot change this decision with a prompt.';
by('detail').textContent='A department credential is verified with scrypt and a constant-time comparison. The server derives an owner hash from the department scope and a random HttpOnly browser cookie, overwrites owner metadata on thread operations, and filters thread-search results again before returning them. Workspace routes also authorize the thread before resolving its disk root.';
by('limit').textContent='This is department entry authentication and browser-bound isolation. It is not employee SSO, organizational role authorization, or collaborative identity across devices. A new browser has a different owner. The unregistered legacy-target path is a separate compatibility path; do not treat it as enterprise IAM.';
by('contract').textContent='registered department request\n  → same-origin check\n  → verify department entry credential\n  → owner = SHA256(department_scope + browser_token)\n  → allow thread-scoped route\n  → compare stored thread owner\n  → forward stream\n\nChanging a thread ID or owner field in the request does not grant ownership.';
by('evidence-note').textContent='Implementation anchors: resolveBackendDepartmentRequest · verifyPassword · browserOwner · authorizeThread · workspaceContextForRequest. This simulator follows the registered-department request path; it does not send credentials. The source guard checks Origin / Sec-Fetch-Site and also accepts its same-host compatibility case; it is not a strict scheme-host-port equality test.';}
function routing(){const dept=state.department==='general'?(state.group==='office'?'General office':'General operations'):state.department==='finance'?'Finance':state.department==='legal'?'Legal':state.department==='works'?'Infrastructure':'Signals';
by('visual').innerHTML=`<div class="ctrl-route-map"><div>${card('USER SELECTS',state.group==='office'?'Office profile':'Operations profile','ctrl-blue')}<span class="ctrl-down">↓</span>${card('CREDENTIAL CHECK',dept,'ctrl-ok')}</div><div class="ctrl-route-arrow" aria-hidden="true">→</div><div class="ctrl-cell"><span class="ctrl-mono">ONE REGISTERED DEPARTMENT PROCESS</span><h4>${dept} backend</h4><div class="ctrl-cell-grid">${card('EXECUTION','Same Agent code')}${card('CONTEXT','Own knowledge root')}${card('FILES','Per-thread disk root')}${card('STATE','Own dev checkpoint store')}</div></div><div class="ctrl-route-side"><span class="ctrl-mono">MODEL ENDPOINT</span><strong>Configured per process</strong><p>A tool can also call its own data, OCR, or ASR service.</p></div></div>`;
by('status').textContent=`The registry routes this request to the fixed ${dept} backend. The launcher starts separate department processes. It does not select the least busy backend or transfer a conversation to another department.`;
by('detail').textContent='Two UI profiles filter the department selection: six office and four operations entries. Each department has its own configured backend target, workspace, knowledge, logs, and local runtime directory. A selected group changes resource scope; the same create_deep_agent construction and tool list are loaded by each process.';
by('limit').textContent='Separate directories and processes are logical isolation, not independent containers or hardware failure domains. The launcher supervises processes; it is not a request scheduler. Automatic department-to-department delegation, shared employee accounts, and live workload migration are not implemented here.';
by('contract').textContent='profile → selected registered department\n        → validate department credential\n        → fixed backend target\n        → department root / thread workspace\n        → same Agent + department-scoped resources\n\nTool choice happens inside the Agent loop.\nBackend choice here is registry routing, not load balancing.';
by('evidence-note').textContent='Implementation anchors: SYSTEM_PROFILES · departmentTargetUrl · department registry · department launcher · workspaceRootForThread. Counts describe the checked source configuration, not an availability guarantee.';}
function scheduling(){const candidates=[{id:'A',jobs:state.load,hit:state.locality ? 0.8 : 0,free:state.memory?1:8,scope:true},{id:'B',jobs:2,hit:state.locality ? 0.1 : 0,free:12,scope:true},{id:'C',jobs:0,hit:.95,free:16,scope:false}].map(w=>({...w,cost:w.jobs*40+60*(1-w.hit),eligible:w.scope&&w.free>=4}));const best=candidates.filter(w=>w.eligible).sort((a,b)=>a.cost-b.cost)[0];
by('visual').innerHTML=`<div class="ctrl-admission"><span>Scoped request</span><b>→</b><span>Fair admission queue</span><b>→</b><span>Model + memory eligibility</span><b>→</b><span>Queue cost + prefix locality</span></div><div class="ctrl-workers">${candidates.map(w=>`<div class="ctrl-worker ${w.id===best.id?'ctrl-selected':''} ${!w.eligible?'ctrl-excluded':''}"><div><h4>Worker ${w.id}</h4><span>${w.id===best.id?'SELECTED':!w.eligible?'EXCLUDED':'ELIGIBLE'}</span></div><p>${w.scope?'Same department + compatible model':'Different department / isolation domain'}</p><div class="ctrl-queue">${Array.from({length:8},(_,i)=>`<i class="${i<w.jobs?'filled':''}"></i>`).join('')}</div><dl><div><dt>Queued work</dt><dd>${w.jobs} × 40 ms</dd></div><div><dt>Reusable prefix</dt><dd>${Math.round(w.hit*100)}%</dd></div><div><dt>Free KV blocks</dt><dd>${w.free} / need 4</dd></div><div><dt>Estimated start</dt><dd>${w.eligible?w.cost.toFixed(0)+' ms':'not eligible'}</dd></div></dl></div>`).join('')}</div>`;
by('status').textContent=`Worker ${best.id} wins among eligible candidates: ${best.jobs*40} ms queued work + ${(60*(1-best.hit)).toFixed(0)} ms uncached prefill. Worker C is excluded even with a warmer cache. ${state.memory?'Worker A cannot reserve the required KV blocks.':'Raise A’s queue to see locality lose to waiting time.'}`;
by('detail').textContent='This proposed scheduler separates three decisions: authorize the isolation domain, admit within tenant and memory budgets, then choose a compatible worker using queue delay and reusable-prefix cost. New arrivals can route elsewhere while an existing run keeps its state affinity. Cancelling or finishing a run releases reservations; overload needs backpressure, not unlimited fan-out.';
by('limit').textContent='No central fair queue, worker-cost estimator, automatic KV-aware router, or live memory reservation is wired into the checked application. Model-serving capacity is external to the Agent backend. Numbers here are a deterministic teaching model: 40 ms per queued job, 60 ms cold prefill, 4 required KV blocks.';
by('contract').textContent='eligible(worker) = scope_match\n                 && model_revision_match\n                 && free_KV_blocks >= reservation\n\ncost = estimated_queue_wait\n     + estimated_uncached_prefill\n\nchoose minimum cost among eligible workers\nno eligible capacity → queue with deadline or reject\n\nKeep UI/API, Agent workers, tool services, and inference\ncapacity as distinct queues and scaling boundaries.';
by('evidence-note').innerHTML='Architecture extension. Primary engineering references: <a href="https://docs.vllm.ai/en/latest/design/prefix_caching/" target="_blank" rel="noreferrer">prefix-cache identity and isolation ↗</a> · <a href="https://kubernetes.io/docs/concepts/cluster-administration/flow-control/" target="_blank" rel="noreferrer">fair admission concepts ↗</a>. These references explain mechanisms; they do not imply this application deploys those systems.';}
function render(){({auth,routing,scheduling})[mode]();const out=document.getElementById('ctrl-load-value');if(out)out.value=state.load+' jobs';}
function activate(next,focus=false){mode=next;const title={auth:'Credentials, ownership, then the run.',routing:'Department selection is resource routing.',scheduling:'A warm cache is only one input.'};const description={auth:'The proxy enforces request boundaries before the model sees a query. Explore how each rejection differs.',routing:'Follow the implemented mapping from UI profile to a department process, conversation state, and file roots.',scheduling:'Explore the missing scale-out layer explicitly as a design extension. Change queue pressure and memory eligibility.'};root.querySelectorAll('[data-control]').forEach(b=>{const on=b.dataset.control===mode;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});by('panel').setAttribute('aria-labelledby','ctrl-tab-'+mode);by('provenance').textContent=mode==='scheduling'?'PRODUCTION EXTENSION · SIMULATED':'IMPLEMENTED CONTRACT · SIMULATED INPUT';by('provenance').classList.toggle('ctrl-target',mode==='scheduling');by('detail-label').textContent=mode==='scheduling'?'HOW THIS DESIGN WORKS':'WHAT THE IMPLEMENTATION DOES';by('contract-label').textContent=mode==='scheduling'?'Inspect the proposed scheduling contract':'Inspect the implementation contract';by('panel-title').textContent=title[mode];by('explanation').textContent=description[mode];controls();render();if(focus)by('tab-'+mode).focus();}
root.addEventListener('click',e=>{const b=e.target.closest('[data-control]');if(b)activate(b.dataset.control);});root.addEventListener('input',e=>{const input=e.target.closest('[data-ctrl]');if(!input)return;state[input.dataset.ctrl]=input.type==='checkbox'?input.checked:input.type==='range'?Number(input.value):input.value;if(input.dataset.ctrl==='group'){state.department='general';controls();}render();});root.addEventListener('keydown',e=>{if(!e.target.matches('[data-control]'))return;const modes=['auth','routing','scheduling'];let i=modes.indexOf(mode);if(['ArrowRight','ArrowDown'].includes(e.key))i=(i+1)%3;else if(['ArrowLeft','ArrowUp'].includes(e.key))i=(i+2)%3;else if(e.key==='Home')i=0;else if(e.key==='End')i=2;else return;e.preventDefault();activate(modes[i],true);});activate('auth');
})();
